export const code = async (inputs) => {
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000)
    .toISOString()
    .split('T')[0];
  return { yesterday };
};

export const code = async (inputs) => {
  const emailRaw = inputs.emailRaw;

  const emails = (emailRaw?.results?.messages || []).map(e => {
    const body = e.text || '';
    const urlMatch = body.match(/https?:\/\/[^\s]+/);
    const link = urlMatch ? urlMatch[0] : null;

    const summary = e.text 
      ? e.text.slice(0, 500)
      : e.html
        ? e.html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500)
        : e.textAsHtml
          ? e.textAsHtml.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500)
          : '';

    return {
      title: e.subject,
      link: link,
      summary: summary,
      published: e.date,
      source: typeof e.from === 'string' ? e.from : e.from?.address || ''
    };
  });

  return { emails };
};

export const code = async (inputs) => {
  const feeds = [
    'https://hnrss.org/frontpage',
    'https://techcrunch.com/category/artificial-intelligence/feed/',
    'https://www.technologyreview.com/topic/artificial-intelligence/feed',
    'https://breakingdefense.com/feed/',
    'https://www.theverge.com/ai-artificial-intelligence/rss/index.xml'
  ];

  const results = await Promise.allSettled(
    feeds.map(url => fetch(url).then(r => r.text()))
  );

  const allItems = [];
  const failedSources = [];

  results.forEach((result, i) => {
    if (result.status === 'rejected') {
      failedSources.push(feeds[i]);
      return;
    }

    const xml = result.value;
    const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => {
      const block = m[1];
      const get = tag => {
        const match = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`));
        return match ? (match[1] || match[2] || '').trim() : '';
      };
      return {
        title: get('title'),
        link: get('link'),
        summary: get('description'),
        published: get('pubDate'),
        source: feeds[i]
      };
    }).filter(item => {
      const pub = new Date(item.published);
      const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);
      return pub > cutoff;
    });

    allItems.push(...items);
  });

  return { rss_items: allItems, failed_sources: failedSources };
};

export const code = async (inputs) => {
  const apiKey = inputs.API_KEY;
const raw = inputs.TOPICS?.value || inputs.TOPICS;
const topics = Array.isArray(raw) 
  ? raw 
  : (() => { try { return JSON.parse(raw); } catch { return raw.split(',').map(t => t.trim()).filter(Boolean); } })();

  const results = await Promise.allSettled(
    topics.map(topic =>
      fetch('https://google.serper.dev/news', {
        method: 'POST',
        headers: {
          'X-API-KEY': apiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          q: topic,
          num: 5,
          tbs: 'qdr:d' // last 24 hours
        })
      }).then(r => r.json())
    )
  );

  const allResults = results
    .filter(r => r.status === 'fulfilled')
    .flatMap((r, i) =>
      (r.value.news || []).map(item => ({
        title: item.title,
        link: item.link,
        summary: item.snippet,
        source: item.source,
        published: item.date,
        topic: topics[i]
      }))
    );

  return { search_results: allResults };
};

export const code = async (inputs) => {

  // ==========================================
  // NORMALIZE INPUTS
  // ==========================================

  const searchResults = Array.isArray(inputs.SEARCH_RESULTS) ? inputs.SEARCH_RESULTS : [];
  const rssResults = Array.isArray(inputs.RSS_RESULTS) ? inputs.RSS_RESULTS : [];
  const emailRaw = inputs.EMAIL_RESULTS || {};

  // ==========================================
  // GET TOPICS
  // ==========================================

  const rawTopics = inputs.TOPICS || inputs.INTERESTS || inputs.RELEVANT_TOPICS || [];
  let topics = [];

  if (Array.isArray(rawTopics)) {
    topics = rawTopics;
  } else if (typeof rawTopics === 'string') {
    try {
      const parsed = JSON.parse(rawTopics);
      topics = Array.isArray(parsed) ? parsed : [rawTopics];
    } catch {
      topics = rawTopics.split(',').map(t => t.trim()).filter(Boolean);
    }
  } else if (typeof rawTopics === 'object') {
    topics = rawTopics.topics || rawTopics.interests || [];
  }

  topics = topics.map(t => typeof t === 'string' ? t : t.name || t.topic || '').filter(Boolean).map(t => t.trim());
  const normalizedTopics = topics.map(t => t.toLowerCase());

  // ==========================================
  // PROCESS EMAILS
  // ==========================================

  const emailMessages = emailRaw?.results?.messages || emailRaw?.messages || [];

  const emails = emailMessages.map(e => {
    const body = e.text || e.body || e.snippet || '';
    const urlMatch = body.match(/https?:\/\/[^\s<>"']+/);
    return {
      title: e.subject || '(No subject)',
      link: urlMatch ? urlMatch[0] : null,
      summary: body.slice(0, 1000),
      published: e.date || e.timestamp || null,
      source: typeof e.from === 'string' ? e.from : e.from?.address || e.sender || '',
      source_type: 'email',
      type: 'EMAIL'
    };
  });

  // ==========================================
  // NORMALIZE EXTERNAL RESULTS
  // ==========================================

  const normalizeItem = (item, defaultType = 'WEB') => {
    if (!item) return null;
    return {
      ...item,
      title: item.title || item.name || item.headline || '',
      link: item.link || item.url || item.href || null,
      summary: item.summary || item.description || item.content || item.snippet || '',
      published: item.published || item.date || item.pubDate || item.timestamp || null,
      source: item.source || item.source_name || item.domain || '',
      source_type: item.source_type || defaultType.toLowerCase(),
      type: item.type || defaultType
    };
  };

  const normalizedSearch = searchResults.map(item => normalizeItem(item, 'WEB')).filter(Boolean);
  const normalizedRSS = rssResults.map(item => normalizeItem(item, 'RSS')).filter(Boolean);

  // ==========================================
  // FETCH HACKER NEWS
  // ==========================================

  let hackerNews = [];

  try {
    const response = await fetch('https://hacker-news.firebaseio.com/v0/topstories.json');
    if (!response.ok) throw new Error(`HN API error: ${response.status}`);
    const storyIds = await response.json();
    const topIds = storyIds.slice(0, 30);

    const stories = await Promise.all(
      topIds.map(async (id, index) => {
        try {
          const storyResponse = await fetch(`https://hacker-news.firebaseio.com/v0/item/${id}.json`);
          if (!storyResponse.ok) return null;
          const story = await storyResponse.json();
          if (!story || story.type !== 'story' || !story.title) return null;
          return {
            id: story.id,
            title: story.title,
            link: story.url || `https://news.ycombinator.com/item?id=${story.id}`,
            summary: story.text || '',
            published: story.time ? new Date(story.time * 1000).toISOString() : null,
            source: 'Hacker News',
            source_type: 'hackernews',
            type: 'HACKERNEWS',
            hn_score: story.score || 0,
            comments: story.descendants || 0,
            hn_rank: index + 1,
            hn_id: story.id
          };
        } catch { return null; }
      })
    );

    hackerNews = stories.filter(Boolean);
  } catch (error) {
    console.log('Hacker News fetch failed:', error.message);
  }

  // ==========================================
  // TRUSTED SOURCES
  // ==========================================

  const trustedDomains = [
    'techcrunch.com', 'theverge.com', 'wired.com', 'arstechnica.com',
    'technologyreview.com', 'venturebeat.com', 'reuters.com', 'bloomberg.com',
    'ft.com', 'nature.com', 'science.org', 'openai.com', 'anthropic.com',
    'breakingdefense.com', 'defenseone.com', 'economictimes.com',
    'livemint.com', 'moneycontrol.com', 'businessstandard.com',
    'ycombinator.com', 'unstop.com', 'internshala.com', 'linkedin.com'
  ];

  const isTrusted = (item) => {
    const text = [item.link || '', item.source || ''].join(' ').toLowerCase();
    return trustedDomains.some(domain => text.includes(domain));
  };

  // ==========================================
  // TOPIC RELEVANCE
  // ==========================================

  const getRelevanceScore = (item) => {
    if (!normalizedTopics.length) return 0;
    const text = [item.title || '', item.summary || '', item.source || ''].join(' ').toLowerCase();
    let score = 0;
    normalizedTopics.forEach(topic => {
      if (!topic) return;
      if (text.includes(topic)) score += 10;
      const words = topic.split(/\s+/).filter(word => word.length > 2);
      let matchedWords = 0;
      words.forEach(word => { if (text.includes(word)) { matchedWords += 1; score += 2; } });
      if (words.length > 1 && matchedWords === words.length) score += 5;
    });
    return score;
  };

  // ==========================================
  // COMBINE + SCORE EVERYTHING
  // ==========================================

  const allItems = [
    ...normalizedSearch,
    ...normalizedRSS,
    ...emails,
    ...hackerNews
  ].filter(item => item && item.title);

  const scored = allItems.map(item => {
    const relevance = getRelevanceScore(item);
    const trusted = isTrusted(item);
    const hnPopularity = item.type === 'HACKERNEWS' ? Math.min((item.hn_score || 0) / 10, 20) : 0;
    const hnRankBonus = item.type === 'HACKERNEWS' ? Math.max(0, 15 - (item.hn_rank || 15)) : 0;

    return {
      ...item,
      trusted,
      relevance_score: relevance,
      priority_score: (relevance * 10) + (trusted ? 25 : 0) + hnPopularity + hnRankBonus
    };
  });

  // ==========================================
  // DEDUPLICATE
  // ==========================================

  const seenTitles = new Set();
  const seenLinks = new Set();

  const deduped = scored
    .sort((a, b) => b.priority_score - a.priority_score)
    .filter(item => {
      if (!item || !item.title) return false;
      const normalizedTitle = item.title.toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
      const normalizedLink = item.link ? item.link.toLowerCase().replace(/\/$/, '') : '';
      if (seenTitles.has(normalizedTitle)) return false;
      if (normalizedLink && seenLinks.has(normalizedLink)) return false;
      seenTitles.add(normalizedTitle);
      if (normalizedLink) seenLinks.add(normalizedLink);
      return true;
    });

  // ==========================================
  // CAP AT 20 FOR CLAUDE
  // ==========================================

  const filtered_results = deduped.slice(0, 25);

  // ==========================================
  // OUTPUT
  // ==========================================

  return {
    filtered_results,
    metadata: {
      topics_used: topics,
      total_before_cap: deduped.length,
      search_results: normalizedSearch.length,
      rss_results: normalizedRSS.length,
      email_results: emails.length,
      hackernews_stories: hackerNews.length,
      relevant_stories: filtered_results.filter(i => i.relevance_score > 0).length,
      trusted_stories: filtered_results.filter(i => i.trusted).length
    }
  };
};

